"""Build suspected-duplicate keys from prior claims. The engine does no I/O."""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from datetime import date

from app.domain.engine import SuspectedDuplicateKey, duplicate_identity
from app.domain.states import LineState

_ANCHOR_STATES = frozenset(
    {
        LineState.APPROVED,
        LineState.PARTIALLY_APPROVED,
        LineState.DENIED,
    }
)


@dataclass(frozen=True, slots=True)
class PriorLineAnchor:
    """A previously seen line. Billed amount is intentionally absent (D17)."""

    member_id: str
    provider_id: str
    service_code: str
    service_date: date
    line_state: LineState


def suspected_duplicate_keys_from_prior(
    prior_lines: Iterable[PriorLineAnchor],
) -> frozenset[SuspectedDuplicateKey]:
    """Return keys for terminal prior lines only. NEEDS_REVIEW is never an anchor."""
    keys: set[SuspectedDuplicateKey] = set()
    for line in prior_lines:
        if line.line_state not in _ANCHOR_STATES:
            continue
        keys.add(
            duplicate_identity(
                member_id=line.member_id,
                provider_id=line.provider_id,
                service_code=line.service_code,
                service_date=line.service_date,
            )
        )
    return frozenset(keys)

"""Application-layer prior-claim keys: only terminal lines become anchors."""

from datetime import date

from app.application.prior_duplicates import (
    PriorLineAnchor,
    suspected_duplicate_keys_from_prior,
)
from app.domain.engine import duplicate_identity
from app.domain.states import LineState


def _anchor(state: LineState, *, day: int = 15) -> PriorLineAnchor:
    return PriorLineAnchor(
        member_id="m1",
        provider_id="prov1",
        service_code="PHYSIO-30",
        service_date=date(2026, 3, day),
        line_state=state,
    )


def test_terminal_prior_lines_become_suspected_keys() -> None:
    keys = suspected_duplicate_keys_from_prior(
        (
            _anchor(LineState.APPROVED),
            _anchor(LineState.PARTIALLY_APPROVED, day=16),
            _anchor(LineState.DENIED, day=17),
        )
    )
    assert keys == frozenset(
        {
            duplicate_identity(
                member_id="m1",
                provider_id="prov1",
                service_code="PHYSIO-30",
                service_date=date(2026, 3, 15),
            ),
            duplicate_identity(
                member_id="m1",
                provider_id="prov1",
                service_code="PHYSIO-30",
                service_date=date(2026, 3, 16),
            ),
            duplicate_identity(
                member_id="m1",
                provider_id="prov1",
                service_code="PHYSIO-30",
                service_date=date(2026, 3, 17),
            ),
        }
    )


def test_needs_review_and_under_appeal_are_not_anchors() -> None:
    keys = suspected_duplicate_keys_from_prior(
        (
            _anchor(LineState.NEEDS_REVIEW),
            _anchor(LineState.UNDER_APPEAL, day=16),
            _anchor(LineState.PENDING, day=17),
        )
    )
    assert keys == frozenset()
